/bin/bash -lc "python3 - <<'PY'
import json,re,collections
from pathlib import Path
p=json.loads(Path('packet.json').read_text())
groups=collections.defaultdict(list)
for i,x in enumerate(p['items']):
 groups[tuple(x['fields'])].append((i,x))
for fields,rows in groups.items():
 print('FIELDS',fields,'COUNT',len(rows))
 for i,x in rows:
  q=x['question']
  if q.startswith('Which '):
   print(i,x['id'],re.search(r'Which (Rel-\\d+) change requests that modify clause (\\S+) of TS (\\S+)',q).groups())
  else:
   print(i,x['id'],re.findall(r'(?:R5|RP)-\\d+|TS \\d+\\.\\d+(?:-\\d+)?',q))
PY"

